mapper.update:
UPDATE job
job_name = #{jobName}, job_desc = #{jobDesc}, requirement = #{requirement}, keywords = #{keywords}, salary = #{salary}, work_address = #{workAddress}, work_experience = #{workExperience}, status = #{status},
WHERE id = #{id}

UPDATE job
SET delivery_count = COALESCE(delivery_count, 0) + 1
WHERE id = #{id}

mapper.select:
SELECT j.id, j.job_name, j.job_desc, j.requirement, j.keywords, j.salary, j.work_address, j.work_experience, j.status, j.create_time, j.update_time, ( SELECT COUNT(1) FROM delivery d WHERE d.job_id = j.id ) AS delivery_count FROM job j WHERE j.hr_id = #{hrId}
AND status = #{status}
AND j.job_name LIKE CONCAT('%', #{jobName}, '%')
AND j.salary LIKE CONCAT('%', #{salary}, '%')
AND j.work_address LIKE CONCAT('%', #{workAddress}, '%')
ORDER BY j.create_time DESC, j.id DESC
